        public bool AddEmployee(EmployeeModel employee)
        {
            if (employee == null)
            {
                return false;
            }
            else
            {
                listEmployees.Add(employee);
                return true;
            }
        }

        public bool DeleteById(int id)
        {
            if (id == 0)
            {
                return false;
            }
            else
            {
                listEmployees.Remove(GetById(id));
                return true;
            }
        }

        public List<EmployeeModel> GetAll()
        {
            return listEmployees;
        }

        public EmployeeModel GetById(int id)
        {
            if (id > 0)
            {
                return listEmployees.Where(e => e.Id == id).FirstOrDefault();
            }
            else
            {
                return new EmployeeModel();
            }
        }

        public EmployeeModel GetByName(string name)
        {
            if (!string.IsNullOrEmpty(name))
            {
                return listEmployees.Where(e => e.Name == name).FirstOrDefault();
            }
            else
            {
                return new EmployeeModel();
            }
        }

        public EmployeeModel UpdateEmployee(EmployeeModel employee)
        {
            if (employee != null)
            {
                var data = GetById(employee.Id);
                data.Age = employee.Age;
                data.Name = employee.Name;
                data.Email = employee.Email;
                data.Phone = employee.Phone;
                data.Designation = employee.Designation;
                data.Skill = employee.Skill;
                return data;
            }
            else
            {
                return new EmployeeModel();
            }
        }
    }
